INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM200CDWP', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'A marine biologist tags \\(7\\) sea turtles on the first day of a study. Each subsequent day, the biologist tags \\(3\\) additional turtles. After how many days will the biologist have tagged a total of \\(31\\) sea turtles?', NULL, $lyceon_json$[{"key":"A","text":"\\(7\\)"},{"key":"B","text":"\\(8\\)"},{"key":"C","text":"\\(9\\)"},{"key":"D","text":"\\(10\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of turtles tagged after \\(d\\) days is \\(7 + 3(d - 1)\\), since \\(7\\) are tagged on day 1 and \\(3\\) more on each day after that. Setting \\(7 + 3(d - 1) = 31\\) gives \\(3(d - 1) = 24\\), so \\(d - 1 = 8\\) and \\(d = 9\\). The value \\(8\\) comes from forgetting that the first day already accounts for \\(7\\) turtles and treating \\(d - 1\\) as the answer instead of \\(d\\). The value \\(7\\) results from dividing \\(31 - 7 = 24\\) by \\(3\\) but not adding back the first day. The value \\(10\\) comes from misreading the problem as starting with \\(0\\) turtles on day \\(0\\) and solving \\(3d + 1 = 31\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20BDQLK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university randomly assigns $150$ students to either receive weekly tutoring sessions or to study independently for a semester. At the end of the semester, the tutored group has a significantly higher average exam score than the independent-study group. Which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"Weekly tutoring causes higher exam scores compared to independent study for students at this university."},{"key":"B","text":"Weekly tutoring causes higher exam scores for all college students nationwide."},{"key":"C","text":"Students who seek tutoring are naturally better test-takers than those who study independently."},{"key":"D","text":"There is an association between tutoring and higher exam scores, but causation cannot be established."}]$lyceon_json$::jsonb, 'A', NULL, E'Because participants were randomly assigned to tutoring or independent study, confounding variables are controlled. Random assignment supports a causal conclusion — weekly tutoring caused the higher exam scores. However, the conclusion is limited to the population from which the sample was drawn (students at this university). Extending the causal claim to all college students nationwide overgeneralizes beyond the study population. Attributing the result to pre-existing test-taking ability ignores that random assignment equalizes such differences across groups. Claiming that only association can be established misidentifies this as an observational study when it is in fact a randomized experiment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20FFV4W', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 13)$ and $(5, 31)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$\\left(-\\frac{1}{6}, 0\\right)$"},{"key":"B","text":"$\\left(\\frac{1}{6}, 0\\right)$"},{"key":"C","text":"$\\left(-\\frac{7}{6}, 0\\right)$"},{"key":"D","text":"$\\left(\\frac{7}{6}, 0\\right)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{31-13}{5-2} = \\frac{18}{3} = 6$. Using point-slope form with $(2, 13)$: $y - 13 = 6(x - 2)$, which gives $y = 6x + 1$. Setting $y = 0$: $0 = 6x + 1$, so $x = -\\frac{1}{6}$. The $x$-intercept is $\\left(-\\frac{1}{6}, 0\\right)$. The value $\\left(\\frac{1}{6}, 0\\right)$ comes from a sign error when solving $6x = -1$. The value $\\left(-\\frac{7}{6}, 0\\right)$ results from computing the $y$-intercept as $b = 13 - 6 = 7$ instead of $b = 13 - 6(2) = 1$, then solving $0 = 6x + 7$ to get $x = -\\frac{7}{6}$. The value $\\left(\\frac{7}{6}, 0\\right)$ comes from using $b = -7$ instead of $+1$ and then also making a sign error when solving.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21JKLXT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$74$ is on sale for $\\$55.50$. What is the percent decrease in price?', NULL, $lyceon_json$[{"key":"A","text":"$18.5\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33\\frac{1}{3}\\%$"},{"key":"D","text":"$74.3\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease in price is $74 - 55.50 = 18.50$. The percent decrease is $\\frac{18.50}{74} \\times 100 = 25\\%$. The distractor $18.5\\%$ confuses the dollar decrease ($18.50$) with the percent decrease. The distractor $33\\frac{1}{3}\\%$ results from dividing the decrease by the sale price ($\\frac{18.50}{55.50}$) instead of the original price. The distractor $74.3\\%$ comes from dividing the sale price by the original price and misinterpreting the result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22H0ACZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, the side opposite a $37°$ angle has length $11$. Which of the following expressions gives the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{\\cos(37°)}$"},{"key":"B","text":"$\\frac{11}{\\sin(37°)}$"},{"key":"C","text":"$11 \\cdot \\sin(37°)$"},{"key":"D","text":"$11 \\cdot \\cos(37°)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $\\sin(37°) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{11}{\\text{hypotenuse}}$, solving gives hypotenuse $= \\frac{11}{\\sin(37°)}$. Dividing by $\\cos(37°)$ would be correct if $11$ were the adjacent side, not the opposite side. Multiplying $11$ by $\\sin(37°)$ or $\\cos(37°)$ would yield a value smaller than $11$, which cannot be the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22JGB26', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $9x + 7y = 63$. Line $q$ is perpendicular to line $p$ and passes through the point $(4, -3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\left(0, -\\frac{55}{9}\\right)$"},{"key":"B","text":"$\\left(0, \\frac{55}{9}\\right)$"},{"key":"C","text":"$\\left(0, -\\frac{1}{9}\\right)$"},{"key":"D","text":"$\\left(0, \\frac{1}{9}\\right)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$ in slope-intercept form: $7y = -9x + 63$, so $y = -\\frac{9}{7}x + 9$. The slope of $p$ is $-\\frac{9}{7}$, so the slope of a perpendicular line is $\\frac{7}{9}$. Using the point $(4, -3)$: $-3 = \\frac{7}{9}(4) + b$, giving $-3 = \\frac{28}{9} + b$, so $b = -3 - \\frac{28}{9} = -\\frac{27}{9} - \\frac{28}{9} = -\\frac{55}{9}$. The $y$-intercept is $\\left(0, -\\frac{55}{9}\\right)$. The value $\\left(0, \\frac{55}{9}\\right)$ results from dropping the negative sign on $-3$ and computing $3 + \\frac{28}{9} = \\frac{55}{9}$. The value $\\left(0, -\\frac{1}{9}\\right)$ comes from incorrectly computing $-\\frac{27}{9} + \\frac{28}{9} = \\frac{1}{9}$ and then negating. The value $\\left(0, \\frac{1}{9}\\right)$ results from the same arithmetic error without the final negation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22VDZ4C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A data set of $30$ observations has a line of best fit $y = -0.85x + 47.3$. The correlation coefficient is $r = -0.92$. A new observation at $x = 40$ has an actual $y$-value of $16$. Which of the following is true about this observation?', NULL, $lyceon_json$[{"key":"A","text":"The residual is $2.7$, and the point lies above the line of best fit."},{"key":"B","text":"The residual is $-2.7$, and the point lies below the line of best fit."},{"key":"C","text":"The residual is $16$, and the point lies on the $x$-axis."},{"key":"D","text":"The residual is $-2.7$, and the point lies above the line of best fit."}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value at $x = 40$ is $y = -0.85(40) + 47.3 = -34 + 47.3 = 13.3$. The residual is actual minus predicted: $16 - 13.3 = 2.7$. A positive residual means the actual value is greater than the predicted value, so the point lies above the line of best fit. The distractor stating $-2.7$ below the line reverses the subtraction order (predicted minus actual). The distractor stating the residual is $16$ confuses the actual $y$-value with the residual, reflecting a fundamental misunderstanding of what a residual measures. The distractor stating $-2.7$ above the line contradicts itself, since a negative residual means the point is below the line, not above it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230HBEN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2 \\cdot 7x^5$?', NULL, $lyceon_json$[{"key":"A","text":"$21x^{7}$"},{"key":"B","text":"$10x^{7}$"},{"key":"C","text":"$21x^{10}$"},{"key":"D","text":"$10x^{10}$"}]$lyceon_json$::jsonb, 'A', NULL, E'When multiplying monomials, multiply the coefficients ($3 \\times 7 = 21$) and add the exponents ($2 + 5 = 7$), giving $21x^{7}$. The result $10x^{7}$ comes from adding the coefficients instead of multiplying them. The result $21x^{10}$ comes from multiplying the exponents instead of adding them. The result $10x^{10}$ combines both errors: adding coefficients and multiplying exponents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23L6TEC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up the wholesale price of an item by $40\\%$ to set the retail price. During a clearance event, the store discounts the retail price by $d\\%$ and sells the item at a loss of $9\\%$ relative to the wholesale price. What is the value of $d$?', NULL, $lyceon_json$[{"key":"A","text":"$31$"},{"key":"B","text":"$35$"},{"key":"C","text":"$45$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the wholesale price be $W$. The retail price is $1.40W$. After a $d\\%$ discount, the selling price is $1.40W \\times \\left(1 - \\frac{d}{100}\\right)$. A $9\\%$ loss on wholesale means the selling price is $0.91W$. Setting these equal: $1.40\\left(1 - \\frac{d}{100}\\right) = 0.91$, so $1 - \\frac{d}{100} = \\frac{0.91}{1.40} = 0.65$, giving $d = 35$. The distractor $31$ results from computing $40 - 9 = 31$, naively subtracting the two percentages. The distractor $45$ comes from incorrectly dividing the loss percentage by the markup percentage ($\\frac{9}{40} \\times 100 = 22.5$) and then doubling it. The distractor $49$ arises from adding the markup and loss percentages ($40 + 9$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24KTDFB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 5x^3 - 2$. What is the value of $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$133$"},{"key":"B","text":"$135$"},{"key":"C","text":"$13$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $g(3) = 5(3)^3 - 2 = 5(27) - 2 = 135 - 2 = 133$. The value $135$ results from computing $5(27)$ but forgetting to subtract $2$. The value $13$ comes from computing $5(3) - 2 = 13$, ignoring the cube exponent entirely. The value $43$ comes from computing $5(9) - 2 = 43$, squaring instead of cubing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24ZW4X8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $x^2 + 6x = 27$, what is the sum of all solutions to the equation?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$6$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting as $x^2 + 6x - 27 = 0$, this factors as $(x + 9)(x - 3) = 0$, giving solutions $x = -9$ and $x = 3$. Their sum is $-9 + 3 = -6$. Equivalently, by Vieta''s formulas the sum of roots is $-\\frac{6}{1} = -6$. The value $6$ results from dropping the negative sign when applying the formula. The value $-3$ represents only the negative of one root. The value $3$ represents only the positive root rather than the sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25MHDI2', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the following system of equations? $$5x + 2y = 29$$ $$x - 2y = 1$$', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates $y$: $(5x + 2y) + (x - 2y) = 29 + 1$, giving $6x = 30$, so $x = 5$. To verify, substitute back: $5 - 2y = 1$ gives $y = 2$, and $5(5) + 2(2) = 29$ confirms the solution. The value $3$ results from an arithmetic error such as computing $6x = 18$. The value $4$ could arise from a substitution mistake. The value $7$ might come from confusing $x$ with the sum $x + y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
