INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26049NM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cartographer uses a scale where $3$ centimeters on the map represents $14$ kilometers of actual distance. Two cities are $8.4$ centimeters apart on the map. What is the actual distance, in kilometers, between the two cities?', NULL, $lyceon_json$[{"key":"A","text":"$36.4$"},{"key":"B","text":"$39.2$"},{"key":"C","text":"$42$"},{"key":"D","text":"$50.4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the proportion $\\frac{3 \\text{ cm}}{14 \\text{ km}} = \\frac{8.4 \\text{ cm}}{d \\text{ km}}$, cross-multiplying gives $3d = 14 \\times 8.4 = 117.6$, so $d = 39.2$ km. The distractor $36.4$ comes from an arithmetic error such as computing $14 \\times 2.6$ instead of $14 \\times 2.8$. The distractor $42$ arises from incorrectly setting $d = 8.4 \\times 5$ by rounding the scale factor. The distractor $50.4$ results from multiplying $8.4 \\times 6$ as if the scale factor were $6$ instead of $\\frac{14}{3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26E407V', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 13x - 47$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$112$"},{"key":"C","text":"$-18$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 5$: $g(5) = 13(5) - 47 = 65 - 47 = 18$. The value $112$ comes from adding $47$ instead of subtracting it ($65 + 47 = 112$). The value $-18$ results from reversing the subtraction ($47 - 65 = -18$). The value $22$ comes from an arithmetic slip such as computing $13 \\times 5 = 69$ and then $69 - 47 = 22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26EKYRY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $250$ households and finds a sample mean monthly electricity bill of $\\$127$ with a margin of error of $\\$11$. A second researcher surveys a random sample of $1{,}000$ households from the same population and finds a sample mean of $\\$131$ with a margin of error of $\\$6$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The second survey's confidence interval is narrower because the sample size is larger."},{"key":"B","text":"The first survey is more accurate because its sample mean is lower."},{"key":"C","text":"The two surveys contradict each other, so at least one must be flawed."},{"key":"D","text":"The margin of error is larger for the second survey because it sampled more households."}]$lyceon_json$::jsonb, 'A', NULL, E'A larger sample size reduces the margin of error, producing a narrower confidence interval. The second survey, with $1{,}000$ households, has a margin of error of $\\$6$ compared to $\\$11$ for the first survey of $250$ households, consistent with this principle. A lower sample mean does not indicate greater accuracy — accuracy relates to how close the estimate is to the true population value, which is unknown. The two intervals ($\\$116$–$\\$138$ and $\\$125$–$\\$137$) overlap substantially, so there is no contradiction. Claiming the margin of error increases with sample size reverses the actual relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27BQHD2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher observes that among $1{,}200$ adults, those who eat breakfast daily have lower rates of heart disease than those who skip breakfast. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between eating breakfast daily and lower rates of heart disease."},{"key":"B","text":"Eating breakfast daily causes lower rates of heart disease."},{"key":"C","text":"Skipping breakfast causes heart disease."},{"key":"D","text":"If all adults ate breakfast daily, heart disease rates would decline."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study is observational — the researcher observed existing behaviors rather than randomly assigning participants to groups — confounding variables may explain the difference. Only an association can be established, not causation. Claiming that eating breakfast causes lower heart disease rates or that skipping breakfast causes heart disease both draw causal conclusions from an observational design, which cannot control for confounders such as overall lifestyle habits. Predicting that heart disease rates would decline if all adults ate breakfast assumes a causal relationship not supported by the study design.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM283BC90', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = 3(2)^x$. By what factor does the value of $f(x)$ increase when $x$ increases by $4$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'When $x$ increases by $4$, the new function value is $f(x+4) = 3(2)^{x+4} = 3(2)^x \\cdot 2^4 = 16 \\cdot f(x)$. The factor of increase is $2^4 = 16$. This question tests understanding of exponential growth behavior: for a function of the form $a \\cdot b^x$, increasing $x$ by $k$ multiplies the output by $b^k$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2889FQE', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for $\\$13$ each and child tickets for $\\$7$ each. On a certain evening, the theater sold $85$ tickets and collected a total of $\\$859$. How many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$37$"},{"key":"C","text":"$41$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'D', NULL, E'Let $a$ be the number of adult tickets and $c$ be the number of child tickets. The system is $a + c = 85$ and $13a + 7c = 859$. Substituting $c = 85 - a$ into the revenue equation: $13a + 7(85 - a) = 859$, which simplifies to $13a + 595 - 7a = 859$, so $6a = 264$ and $a = 44$. Then $c = 41$. The value $41$ is the number of child tickets, not adult tickets. The value $34$ results from swapping the ticket prices in the revenue equation. The value $37$ arises from an arithmetic slip such as computing $6a = 222$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM295IGWM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of $37$ students, $19$ study French, $23$ study Spanish, and $9$ study both languages. A student is selected at random from those who study at least one of the two languages. Given that the selected student studies French, what is the probability that the student does NOT study Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{10}{33}$"},{"key":"B","text":"$\\frac{10}{19}$"},{"key":"C","text":"$\\frac{9}{19}$"},{"key":"D","text":"$\\frac{14}{33}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Students studying at least one language number $19 + 23 - 9 = 33$. We condition on studying French: all $19$ French students are in this group. Of those $19$, exactly $9$ also study Spanish, so $19 - 9 = 10$ study French only. The conditional probability is $\\frac{10}{19}$. The value $\\frac{10}{33}$ incorrectly uses the total number of language students as the denominator instead of the number of French students. The value $\\frac{9}{19}$ gives the probability that a French student DOES study Spanish, answering the complement of what was asked. The value $\\frac{14}{33}$ uses $23 - 9 = 14$ (Spanish-only students) over $33$, confusing Spanish-only with French-only.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29K234I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has the equation $(x - 7)^2 + (y + 4)^2 = 81$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$81$"},{"key":"B","text":"$9$"},{"key":"C","text":"$\\sqrt{7}$"},{"key":"D","text":"$40.5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$. Here $r^2 = 81$, so $r = \\sqrt{81} = 9$. The answer $81$ confuses $r^2$ with $r$. The answer $\\sqrt{7}$ incorrectly takes the square root of a coordinate in the center rather than the right-hand side. The answer $40.5$ halves $81$, confusing a diameter-related formula with the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29UAGGT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ voters in a city found that $54\\%$ support a proposed park renovation. The margin of error for the survey is $\\pm 4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $50\\%$ and $58\\%$ of all voters in the city are likely to support the renovation."},{"key":"B","text":"Exactly $54\\%$ of all voters in the city support the renovation."},{"key":"C","text":"Between $50\\%$ and $58\\%$ of the $400$ voters sampled support the renovation."},{"key":"D","text":"If the survey were repeated, $54\\%$ of voters would support the renovation every time."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of $\\pm 4\\%$ around a sample proportion of $54\\%$ yields a confidence interval from $50\\%$ to $58\\%$ for the population parameter. This means the plausible range for the true proportion of all voters supporting the renovation is $50\\%$ to $58\\%$. Claiming exactly $54\\%$ of all voters support the renovation ignores sampling variability. Applying the interval to the sample rather than the population misunderstands the purpose of a margin of error, which estimates the population parameter. Asserting the result would be identical in every repetition confuses a point estimate with certainty.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29VN51X', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9a^4b^3 - 15a^2b^5}{3a^2b^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3a^2b - 5b^3$"},{"key":"B","text":"$3a^2b - 5a^4b^3$"},{"key":"C","text":"$6a^2b - 12b^3$"},{"key":"D","text":"$3a^6b^5 - 5a^4b^7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Divide each term by $3a^2b^2$: $\\frac{9a^4b^3}{3a^2b^2} = 3a^{4-2}b^{3-2} = 3a^2b$ and $\\frac{15a^2b^5}{3a^2b^2} = 5a^{2-2}b^{5-2} = 5b^3$. The result is $3a^2b - 5b^3$. The expression $3a^2b - 5a^4b^3$ arises from dividing only the coefficient of the second term without subtracting exponents. The expression $6a^2b - 12b^3$ comes from subtracting $3$ from each coefficient instead of dividing. The expression $3a^6b^5 - 5a^4b^7$ results from adding exponents instead of subtracting when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ABXR3K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers recruit $300$ volunteers from a local fitness center and randomly assign them to either a high-protein diet group or a standard diet group for $12$ weeks. The high-protein group shows significantly greater muscle mass gain. A fitness magazine reports: "New study proves high-protein diets build more muscle in the general population." Which of the following best identifies the flaw in the magazine''s report?', NULL, $lyceon_json$[{"key":"A","text":"The study was observational, so no causal claim can be made."},{"key":"B","text":"The sample was volunteers from a fitness center, so the results cannot be generalized to the general population."},{"key":"C","text":"The study did not use random assignment, so confounding variables were not controlled."},{"key":"D","text":"A $12$-week study is too short to draw any conclusions about diet and muscle gain."}]$lyceon_json$::jsonb, 'B', NULL, E'The study used random assignment, so a causal conclusion about the effect of a high-protein diet on muscle mass is warranted for the study population. However, the volunteers were recruited from a fitness center — a convenience sample — so the results cannot be generalized to the general population, only to similar fitness-center members. The flaw in the magazine''s claim is overgeneralization, not lack of causation. Claiming the study was observational is incorrect because participants were randomly assigned to diet groups. Claiming no random assignment was used contradicts the study design described. Asserting that $12$ weeks is too short is an unsupported objection — the study did find a significant difference within that timeframe, and nothing in the design makes the duration inherently insufficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AH26O4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ employees found that $74$ commute by car only, $53$ commute by train only, $31$ commute by both car and train, and the rest use other methods. If an employee who commutes by car (either only or in combination with train) is selected at random, what is the probability that this employee also commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{200}$"},{"key":"B","text":"$\\frac{31}{105}$"},{"key":"C","text":"$\\frac{31}{84}$"},{"key":"D","text":"$\\frac{53}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of employees who commute by car (only or with train) is $74 + 31 = 105$. Among these, $31$ also commute by train. The conditional probability is $\\frac{31}{105}$. The value $\\frac{31}{200}$ incorrectly uses the total number of employees as the denominator instead of conditioning on car commuters. The value $\\frac{31}{84}$ results from using $53 + 31 = 84$ (train commuters) as the denominator, conditioning on the wrong group. The value $\\frac{53}{200}$ counts only train-only commuters over the total, answering a different question entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BMNRRH', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A store charges a flat repair fee of $\\$37$ plus $\\$19$ per hour of labor. A second store charges no flat fee but $\\$28$ per hour of labor. For how many hours of labor do both stores charge the same total amount? Express your answer as a fraction if it is not an integer.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '37/9', ARRAY['37/9', '4.111'], E'Let $h$ represent the number of hours. The first store charges $37 + 19h$ and the second charges $28h$. Setting them equal: $37 + 19h = 28h$. Subtracting $19h$ from both sides gives $37 = 9h$, so $h = \\frac{37}{9}$. This is approximately $4.11$ hours. A common error is setting up the equation as $37 + 19h = 28$ (omitting the variable on the right), yielding a negative result. Another error is subtracting in the wrong direction to get $37 = -9h$, producing a negative value that does not make sense in context.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BR1LDU', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A small business owner charges $\\$17$ per hour for consulting and pays a fixed monthly software fee of $\\$263$. If the owner needs to earn more than $\\$1{,}500$ in profit per month after the software fee, which inequality represents the minimum number of hours, $h$, the owner must work?', NULL, $lyceon_json$[{"key":"A","text":"$17h - 263 > 1500$"},{"key":"B","text":"$17h + 263 > 1500$"},{"key":"C","text":"$17h - 263 \\geq 1500$"},{"key":"D","text":"$263 - 17h > 1500$"}]$lyceon_json$::jsonb, 'A', NULL, E'The owner''s profit is revenue minus cost: $17h - 263$. The problem states the profit must be more than $\\$1{,}500$, so the correct inequality is $17h - 263 > 1500$. Adding $263$ to the software fee instead of subtracting it would incorrectly model the fee as additional income rather than a cost. Using $\\geq$ instead of $>$ changes the meaning from ''more than'' to ''at least,'' which does not match the problem''s wording. Subtracting revenue from cost ($263 - 17h$) reverses the relationship entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D7NFVS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has the equation \\((x + 7)^2 + (y - 11)^2 = 169\\). A point on the circle has coordinates \\((-7, k)\\) where \\(k > 0\\). What is the value of \\(k\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(13\\)"},{"key":"B","text":"\\(24\\)"},{"key":"C","text":"\\(22\\)"},{"key":"D","text":"\\(-2\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting \\(x = -7\\) into \\((x + 7)^2 + (y - 11)^2 = 169\\) gives \\(0 + (y - 11)^2 = 169\\). Taking the square root: \\(y - 11 = \\pm 13\\), so \\(y = 24\\) or \\(y = -2\\). Since \\(k > 0\\), the answer is \\(24\\). The value \\(13\\) comes from recognizing \\(\\sqrt{169} = 13\\) but forgetting to add the center''s \\(y\\)-coordinate of \\(11\\). The value \\(22\\) results from incorrectly doubling the radius component, such as computing \\(11 + 11\\). The value \\(-2\\) is the other solution \\(11 - 13\\) but does not satisfy the condition \\(k > 0\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DP3PD4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages, in years, of $9$ members of a hiking club are: $23, 27, 29, 31, 34, 37, 41, 43, 58$. If the oldest member ($58$ years old) leaves the club, which of the following statements correctly describes the effect on the mean and median ages of the remaining members?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and median decrease."},{"key":"B","text":"The mean decreases, but the median remains the same."},{"key":"C","text":"The mean decreases, but the median increases."},{"key":"D","text":"Both the mean and median remain the same."}]$lyceon_json$::jsonb, 'A', NULL, E'With $9$ members, the mean is $\\frac{323}{9} \\approx 35.9$ and the median (5th value) is $34$. After removing $58$, the $8$ remaining ages have mean $\\frac{265}{8} = 33.125$ (decreased) and median $\\frac{31 + 34}{2} = 32.5$ (decreased from $34$). So both the mean and median decrease. The distractor stating the mean decreases but the median stays the same incorrectly assumes the median is unaffected because no central values were removed, overlooking that with an even count the median becomes the average of two values. The distractor stating the median increases contradicts the calculation. The distractor stating both remain the same ignores the impact of removing an outlier.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E94KNP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to the equation $x^2 + 5x - 84 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$-12$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring $x^2 + 5x - 84 = 0$ gives $(x + 12)(x - 7) = 0$, so $x = -12$ or $x = 7$. Since the question asks for the positive solution, the answer is $7$. The value $12$ results from a sign error when reading the factor $(x + 12) = 0$. The value $-7$ comes from a sign error with the other factor, and $-12$ is the negative root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EP57R7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In $\\triangle PQR$, the measure of $\\angle P$ is $41°$ and the measure of $\\angle Q$ is $67°$. An exterior angle is formed at vertex $R$. What is the measure, in degrees, of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$72°$"},{"key":"B","text":"$108°$"},{"key":"C","text":"$139°$"},{"key":"D","text":"$113°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180° - 41° - 67° = 72°$. The exterior angle at $R$ is supplementary to it: $180° - 72° = 108°$. Equivalently, by the exterior angle theorem, the exterior angle equals the sum of the two non-adjacent interior angles: $41° + 67° = 108°$. The answer $72°$ is the interior angle at $R$, not the exterior angle. The answer $139°$ could arise from incorrectly adding $67° + 72°$. The answer $113°$ comes from an error such as computing $41° + 72°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HN9ARN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records the following exam scores for $11$ students: $62, 68, 71, 73, 76, 79, 82, 85, 88, 91, 97$. The teacher decides to add a $13$-point bonus to every score, but any adjusted score above $100$ is capped at $100$. What is the median of the adjusted scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '92', ARRAY['92'], E'Adding $13$ to each score gives: $75, 81, 84, 86, 89, 92, 95, 98, 100, 100, 100$ (the last three are capped since $88 + 13 = 101$, $91 + 13 = 104$, and $97 + 13 = 110$ all exceed $100$). With $11$ values, the median is the $6$th value in order, which is $92$. The uncapped value $79 + 13 = 92$ falls at the $6$th position and is not affected by the cap.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HQHS40', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $11x - 4y = 44$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -11)$"},{"key":"B","text":"$(0, 11)$"},{"key":"C","text":"$(0, 4)$"},{"key":"D","text":"$(4, 0)$"}]$lyceon_json$::jsonb, 'A', NULL, E'To find the $y$-intercept, set $x = 0$: $11(0) - 4y = 44$, so $-4y = 44$ and $y = -11$. The $y$-intercept is $(0, -11)$. The point $(0, 11)$ results from dropping the negative sign when dividing $44$ by $-4$. The value $(0, 4)$ comes from confusing the coefficient of $y$ with the intercept. The point $(4, 0)$ is the $x$-intercept, not the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J7L8VR', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'Consider the system of equations: $$7x - 3y = 11$$ $$2x + 3y = 34$$ What is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Adding the two equations eliminates $y$: $(7x - 3y) + (2x + 3y) = 11 + 34$, which gives $9x = 45$, so $x = 5$. Substituting into the second equation: $2(5) + 3y = 34$, so $3y = 24$ and $y = 8$. Therefore $x + y = 5 + 8 = 13$. Verification: $7(5) - 3(8) = 35 - 24 = 11$ and $2(5) + 3(8) = 10 + 24 = 34$, confirming both equations are satisfied.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KXNKTJ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A delivery service charges a base fee of $\\$11$ plus $\\$3$ per mile for standard delivery and a flat rate of $\\$47$ for express delivery. For which distances, in miles, is express delivery strictly cheaper than standard delivery?', NULL, $lyceon_json$[{"key":"A","text":"More than $12$ miles"},{"key":"B","text":"More than $\\frac{58}{3}$ miles"},{"key":"C","text":"At least $12$ miles"},{"key":"D","text":"More than $11$ miles"}]$lyceon_json$::jsonb, 'A', NULL, E'Standard delivery costs $11 + 3m$ dollars for $m$ miles. Express delivery is strictly cheaper when $47 < 11 + 3m$, which simplifies to $36 < 3m$, giving $m > 12$. So express is cheaper for distances of more than $12$ miles. The answer $\\frac{58}{3}$ miles results from incorrectly setting up the inequality as $47 + 11 > 3m$. The phrase ''at least $12$ miles'' incorrectly includes $m = 12$, where both services cost exactly $\\$47$, so express is not strictly cheaper at that distance. The value $11$ miles arises from a computational slip such as dividing $33$ by $3$ instead of $36$ by $3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L5ISXE', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank initially contains $340$ liters of water and is being drained at a constant rate of $17$ liters per minute. If $V(t)$ represents the volume of water in the tank, in liters, after $t$ minutes of draining, what does the value $17$ represent in the function $V(t) = 340 - 17t$?', NULL, $lyceon_json$[{"key":"A","text":"The rate at which the volume decreases, in liters per minute"},{"key":"B","text":"The initial volume of water in the tank, in liters"},{"key":"C","text":"The time it takes for the tank to empty, in minutes"},{"key":"D","text":"The volume remaining after $1$ minute, in liters"}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $V(t) = 340 - 17t$, the coefficient of $t$ is $-17$, meaning the volume decreases by $17$ liters each minute. The value $17$ represents the rate of decrease in liters per minute. Confusing it with the initial volume is incorrect because the initial volume is $340$. Interpreting it as the time to empty confuses the rate with $\\frac{340}{17} = 20$ minutes. Calling it the volume remaining after $1$ minute is wrong because $V(1) = 340 - 17 = 323$ liters, not $17$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LP9DGX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $h$ is defined by $h(x) = \\frac{5x - 23}{11}$. If $h(a) = \\frac{7}{11}$, what is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Setting $h(a) = \\frac{7}{11}$: $\\frac{5a - 23}{11} = \\frac{7}{11}$. Since the denominators are equal, $5a - 23 = 7$. Adding $23$ to both sides gives $5a = 30$, so $a = 6$. A common error is cross-multiplying incorrectly or forgetting to add $23$, yielding $a = \\frac{7}{5}$. Another error is multiplying both sides by $11$ but then dividing $7$ by $5$ to get $\\frac{7}{5}$, neglecting the $-23$ term entirely.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MBWMTJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle \\(PQR\\), angle \\(P\\) measures \\(37°\\) and angle \\(Q\\) measures \\(59°\\). What is the measure, in degrees, of angle \\(R\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(74\\)"},{"key":"B","text":"\\(84\\)"},{"key":"C","text":"\\(96\\)"},{"key":"D","text":"\\(104\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is \\(180°\\). Therefore, angle \\(R = 180° - 37° - 59° = 84°\\). The value \\(74°\\) results from subtracting \\(37 + 59 = 96\\) then computing \\(180 - 96\\) incorrectly as \\(74\\) (an arithmetic slip of \\(10\\)). The value \\(96°\\) comes from computing \\(37 + 59 = 96\\) and reporting the sum of the other two angles instead of the remaining angle. The value \\(104°\\) results from subtracting only one angle, such as \\(180 - 37 - 59\\) miscomputed as \\(180 - 76\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MJB1GO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the age (in months) and height (in centimeters) of $20$ saplings. The line of best fit is $h = 1.3a + 22$, where $a$ is the age in months and $h$ is the height in centimeters. One sapling is $18$ months old and has an actual height of $48$ centimeters. What is the residual for this sapling?', NULL, $lyceon_json$[{"key":"A","text":"$3.6$"},{"key":"B","text":"$2.6$"},{"key":"C","text":"$-2.6$"},{"key":"D","text":"$-3.6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted height at $a = 18$ is $h = 1.3(18) + 22 = 23.4 + 22 = 45.4$ cm. The residual is actual minus predicted: $48 - 45.4 = 2.6$. The distractor $3.6$ results from an arithmetic slip such as computing the predicted height as $44.4$ instead of $45.4$. The distractor $-2.6$ uses the correct magnitude but reverses the sign by computing predicted minus actual instead of actual minus predicted. The distractor $-3.6$ combines both errors: the arithmetic slip and the sign reversal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NK216S', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{4x^2 + 28x + 49}{2x + 7} = ax + b$ for all values of $x$ where the expression is defined, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The numerator $4x^2 + 28x + 49$ factors as $(2x + 7)^2$ because $(2x)^2 = 4x^2$, $2(2x)(7) = 28x$, and $7^2 = 49$. Dividing $(2x + 7)^2$ by $(2x + 7)$ gives $2x + 7$. So $a = 2$ and $b = 7$, meaning $a + b = 2 + 7 = 9$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O64HIX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle has the equation $x^2 + y^2 - 10x + 6y - 47 = 0$. What is the area of the circle? Express your answer as $k\\pi$ and give the value of $k$.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '81', ARRAY['81'], E'Complete the square for $x$: $x^2 - 10x = (x - 5)^2 - 25$. Complete the square for $y$: $y^2 + 6y = (y + 3)^2 - 9$. Substituting: $(x - 5)^2 - 25 + (y + 3)^2 - 9 - 47 = 0$, so $(x - 5)^2 + (y + 3)^2 = 81$. The radius is $r = 9$ and $r^2 = 81$. The area is $\\pi r^2 = 81\\pi$, so $k = 81$. A common error is forgetting to add both completing-the-square constants to the right side, yielding an incorrect radius. Another error is reporting the radius $9$ instead of $r^2 = 81$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OAAFL9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands $47$ meters from the base of a building. From this point, the angle of elevation to the top of the building is $58°$. From the same point, the angle of elevation to a communications antenna mounted on top of the building is $63°$. What is the height, in meters, of the antenna alone? (Round to the nearest tenth.)', NULL, $lyceon_json$[{"key":"A","text":"$17.0$"},{"key":"B","text":"$92.2$"},{"key":"C","text":"$75.2$"},{"key":"D","text":"$4.1$"}]$lyceon_json$::jsonb, 'A', NULL, E'The height to the top of the building is $47\\tan(58°) \\approx 47 \\times 1.6003 \\approx 75.2$ meters. The height to the top of the antenna is $47\\tan(63°) \\approx 47 \\times 1.9626 \\approx 92.2$ meters. The antenna height is the difference: $92.2 - 75.2 \\approx 17.0$ meters. The answer $92.2$ is the total height to the top of the antenna, not the antenna alone. The answer $75.2$ is the building height without the antenna. The answer $4.1$ results from an error such as computing $47\\tan(5°)$, incorrectly subtracting the angles first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OO9R0X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A dataset contains the values $11, 14, 14, 17, 19, 23, 27$. What is the median of this dataset?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$17$"},{"key":"C","text":"$17.86$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The dataset has $7$ values already in order. The median is the middle value, which is the $4$th value: $17$. The distractor $14$ is the mode (the most frequently occurring value), not the median. The distractor $17.86$ is approximately the mean ($\\frac{125}{7} \\approx 17.86$), which is a different measure of center. The distractor $19$ is the $5$th value, resulting from miscounting the middle position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OVCMG9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right triangular prism has a triangular base with legs of length $8$ cm and $15$ cm. The prism has a height (depth) of $19$ cm. What is the volume, in cubic centimeters, of the prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1140', ARRAY['1140'], E'The triangular base is a right triangle with legs $8$ and $15$. Its area is $\\frac{1}{2}(8)(15) = 60$ square centimeters. The volume of a prism is base area times height: $60 \\times 19 = 1140$ cubic centimeters. A common error is forgetting the $\\frac{1}{2}$ in the triangle area formula, which would give $8 \\times 15 \\times 19 = 2280$. Another error is computing the hypotenuse ($\\sqrt{64 + 225} = 17$) and incorrectly using it in the volume calculation.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OWKS9C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A chemical solution is made by mixing compound $X$ and compound $Y$ in a ratio of $5:9$ by mass. A technician has $630$ grams of compound $Y$ and an unlimited supply of compound $X$. She makes as much solution as possible using all $630$ grams of compound $Y$. She then removes $280$ grams of the finished solution. How many grams of compound $X$ remain in the leftover solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '250', ARRAY['250'], E'The ratio $X : Y = 5 : 9$ means for every $9$ grams of $Y$, there are $5$ grams of $X$. With $630$ grams of $Y$, the amount of $X$ used is $\\frac{5}{9} \\times 630 = 350$ grams. The total solution is $630 + 350 = 980$ grams. The fraction of the solution that is compound $X$ is $\\frac{350}{980} = \\frac{5}{14}$. After removing $280$ grams of solution, $980 - 280 = 700$ grams remain. The amount of $X$ in the remaining solution is $\\frac{5}{14} \\times 700 = 250$ grams.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PHR17T', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = (x - 4)^2 + 11$. For which value of $x$ does $h(x)$ reach its minimum?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function $h(x) = (x - 4)^2 + 11$ is in vertex form $a(x - h)^2 + k$, where the vertex is at $(4, 11)$. Since the coefficient of the squared term is positive, the parabola opens upward and the minimum occurs at $x = 4$. The value $-4$ results from a sign error, taking the constant inside the parentheses without accounting for the subtraction. The value $11$ is the minimum output value of the function, not the input at which the minimum occurs. The value $-11$ confuses both the sign and the role of the constant term.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SGYL9E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In $\\triangle XYZ$, $\\angle X = 46°$ and $\\angle Y = 83°$. Point $W$ lies on side $\\overline{YZ}$ such that $\\overline{XW}$ bisects $\\angle X$. What is the measure, in degrees, of $\\angle XWY$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '74', ARRAY['74'], E'First, find the third angle: $\\angle Z = 180° - 46° - 83° = 51°$. Since $XW$ bisects $\\angle X$, we have $\\angle YXW = \\frac{46°}{2} = 23°$. In $\\triangle XWY$, the angle sum gives $\\angle XWY = 180° - 83° - 23° = 74°$. Common errors include forgetting to halve $\\angle X$ (using $46°$ instead of $23°$, which would give $51°$) or computing $\\angle XWZ$ in the other sub-triangle instead of $\\angle XWY$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T0SSC5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was $12{,}400$ in 2018. The population increased by $6\\%$ from 2018 to 2019, then decreased by $4\\%$ from 2019 to 2020. What was the population of the town in 2020?', NULL, $lyceon_json$[{"key":"A","text":"$12{,}400$"},{"key":"B","text":"$12{,}648$"},{"key":"C","text":"$12{,}618.24$"},{"key":"D","text":"$12{,}896$"}]$lyceon_json$::jsonb, 'C', NULL, E'After a $6\\%$ increase, the 2019 population is $12{,}400 \\times 1.06 = 13{,}144$. After a $4\\%$ decrease, the 2020 population is $13{,}144 \\times 0.96 = 12{,}618.24$. The distractor $12{,}400$ assumes a $6\\%$ increase followed by a $4\\%$ decrease returns to the original value, reflecting a conceptual misunderstanding that opposite percentages cancel out. The distractor $12{,}648$ applies a net $2\\%$ increase to the original ($12{,}400 \\times 1.02$), incorrectly combining the percentages additively. The distractor $12{,}896$ results from an arithmetic slip when multiplying $13{,}144 \\times 0.96$, incorrectly computing the product.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TBU1EL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization selects a random sample of $600$ adults from a large city and finds that $39\\%$ favor a new transit tax, with a margin of error of $\\pm 3.9\\%$ at the $95\\%$ confidence level. A city council member claims that the majority of adults in the city oppose the transit tax. Which of the following best evaluates this claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the confidence interval for the proportion who favor the tax is entirely below $50\\%$."},{"key":"B","text":"The claim is not supported because $39\\%$ is close enough to $50\\%$ that the difference could be due to sampling error."},{"key":"C","text":"The claim is supported because $39\\%$ is less than $50\\%$."},{"key":"D","text":"The claim cannot be evaluated because the survey only measured support, not opposition."}]$lyceon_json$::jsonb, 'A', NULL, E'The $95\\%$ confidence interval for the proportion favoring the tax runs from $39\\% - 3.9\\% = 35.1\\%$ to $39\\% + 3.9\\% = 42.9\\%$. Since the entire interval is below $50\\%$, more than half the population is estimated to not favor the tax, supporting the council member''s claim. Stating the difference could be due to sampling error ignores that the interval''s upper bound ($42.9\\%$) is well below $50\\%$, meaning sampling variability has been accounted for and the conclusion still holds. Noting only that $39\\% < 50\\%$ without referencing the confidence interval is incomplete reasoning — the sample proportion alone does not establish a population-level claim. Claiming the survey cannot address opposition misunderstands that opposition is the complement of support in a binary question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TC9XZ5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $23$ feet and a width of $11$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$253$"},{"key":"B","text":"$68$"},{"key":"C","text":"$34$"},{"key":"D","text":"$242$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: $23 \\times 11 = 253$ square feet. The answer $68$ computes the perimeter ($2(23 + 11) = 68$) instead of the area. The answer $34$ gives the semi-perimeter ($23 + 11$). The answer $242$ results from a multiplication error such as computing $22 \\times 11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TK6PNM', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A pottery studio charges a flat fee of \\$19 for kiln access plus \\$4 per pound of clay used. A customer wants to spend no more than \\$51 on a single visit. Which inequality represents the maximum number of pounds of clay, \\(p\\), the customer can use?', NULL, $lyceon_json$[{"key":"A","text":"\\(19 + 4p \\leq 51\\)"},{"key":"B","text":"\\(19p + 4 \\leq 51\\)"},{"key":"C","text":"\\(4p - 19 \\leq 51\\)"},{"key":"D","text":"\\(19 + 4p \\geq 51\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of \\$19 plus \\$4 per pound, giving \\(19 + 4p\\). Since the customer wants to spend no more than \\$51, the inequality is \\(19 + 4p \\leq 51\\). The expression \\(19p + 4\\) incorrectly swaps the per-pound rate and the flat fee. The expression \\(4p - 19\\) incorrectly subtracts the flat fee instead of adding it. Using \\(\\geq\\) reverses the direction of the constraint, representing spending at least \\$51 rather than at most.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UA9BXE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours spent studying and the score on a quiz for $15$ students. The line of best fit is $y = 4.7x + 51$, where $x$ is the number of hours studied and $y$ is the quiz score. What does the slope of the line represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The predicted quiz score for a student who did not study"},{"key":"B","text":"The predicted increase in quiz score for each additional hour spent studying"},{"key":"C","text":"The total number of quiz points available"},{"key":"D","text":"The average number of hours all students studied"}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation $y = 4.7x + 51$, the slope $4.7$ represents the predicted increase in quiz score for each additional hour spent studying. The choice describing the predicted score for a student who did not study refers to the $y$-intercept ($51$), not the slope. The choice about total quiz points and the choice about average hours studied are unrelated to what a slope represents in a linear model.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WA4NR1', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 5)}{4} + 7 = 16$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{2}$"},{"key":"B","text":"$4$"},{"key":"C","text":"$\\frac{41}{6}$"},{"key":"D","text":"$\\frac{23}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $7$ from both sides gives $\\frac{3(2x-5)}{4} = 9$. Multiplying both sides by $4$ gives $3(2x-5) = 36$. Distributing yields $6x - 15 = 36$, so $6x = 51$ and $x = \\frac{51}{6} = \\frac{17}{2}$. The value $4$ results from forgetting to multiply by $4$: solving $3(2x-5) = 9$ gives $6x - 15 = 9$, so $6x = 24$ and $x = 4$. The value $\\frac{41}{6}$ comes from adding $5$ instead of $15$ after distributing, solving $6x = 41$. The value $\\frac{23}{6}$ results from an arithmetic error when multiplying $3 \\times 12$, using $38$ instead of $36$, leading to $6x = 23$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WCTCQY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $7$ bottles every $4$ minutes. At this rate, how many bottles does the machine fill in $52$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$84$"},{"key":"B","text":"$91$"},{"key":"C","text":"$104$"},{"key":"D","text":"$364$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{7 \\text{ bottles}}{4 \\text{ minutes}}$. In $52$ minutes the machine fills $\\frac{7}{4} \\times 52 = 91$ bottles. The distractor $84$ results from incorrectly computing $7 \\times 12$ (treating $52 \\div 4$ as $12$ instead of $13$). The distractor $104$ comes from multiplying $52 \\times 2$ rather than using the correct ratio. The distractor $364$ results from multiplying $7 \\times 52$ without dividing by $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XWPUM4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the leg opposite an acute angle has length \\(9\\) and the hypotenuse has length \\(41\\). What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"\\(32\\)"},{"key":"B","text":"\\(38\\)"},{"key":"C","text":"\\(40\\)"},{"key":"D","text":"\\(42\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the Pythagorean theorem, if the legs are \\(9\\) and \\(b\\) and the hypotenuse is \\(41\\), then \\(9^2 + b^2 = 41^2\\). This gives \\(81 + b^2 = 1681\\), so \\(b^2 = 1600\\) and \\(b = 40\\). The value \\(32\\) comes from simply subtracting \\(41 - 9\\) instead of using the Pythagorean theorem. The value \\(38\\) arises from a computational error such as miscalculating \\(41^2\\) or \\(\\sqrt{1600}\\). The value \\(42\\) results from incorrectly setting up the equation as \\(9^2 + 41^2 = b^2\\), treating the hypotenuse as a leg.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZAYKC3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $7$ red marbles, $11$ blue marbles, and $3$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{21}$"},{"key":"B","text":"$\\frac{7}{21}$"},{"key":"C","text":"$\\frac{3}{21}$"},{"key":"D","text":"$\\frac{11}{18}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $7 + 11 + 3 = 21$. The probability of selecting a blue marble is $\\frac{11}{21}$. The value $\\frac{7}{21}$ results from counting red marbles instead of blue. The value $\\frac{3}{21}$ results from counting green marbles instead of blue. The value $\\frac{11}{18}$ results from incorrectly computing the total as $18$ by omitting one color group.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZPOZVZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $7$ cm and a height of $13$ cm. A cone has the same radius and height as the cylinder. What is the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{637\\pi}{3}$"},{"key":"B","text":"$637\\pi$"},{"key":"C","text":"$\\frac{91\\pi}{3}$"},{"key":"D","text":"$\\frac{1274\\pi}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(7)^2(13) = \\frac{1}{3}\\pi(49)(13) = \\frac{637\\pi}{3}$. The answer $637\\pi$ gives the cylinder volume ($\\pi r^2 h$), omitting the $\\frac{1}{3}$ factor. The answer $\\frac{91\\pi}{3}$ uses $r = 7$ instead of $r^2 = 49$ (forgetting to square the radius), computing $\\frac{1}{3}(7)(13)\\pi$. The answer $\\frac{1274\\pi}{3}$ doubles the correct result, possibly from using the diameter instead of the radius.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW249DYFK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, the architect Ernesto Quintana unveiled a library design that incorporated rammed-earth walls and passive cooling _______ the building, completed in 1991, still uses forty-three percent less energy than comparable structures in the same municipality.', $lyceon_json$[{"key":"A","text":"systems."},{"key":"B","text":"systems,"},{"key":"C","text":"systems and,"},{"key":"D","text":"systems:"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two independent clauses: one about Quintana''s 1987 design incorporating rammed-earth walls and passive cooling systems, and another about the building''s energy use after completion in 1991. A period correctly separates these independent clauses. A comma alone after ''systems'' creates a comma splice, which is a sentence boundary error. Placing ''and,'' with a comma after the conjunction is ungrammatical. A colon would require the second clause to explain or elaborate on the first, but the second clause introduces a separate temporal fact rather than explaining the design features.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25EQCC7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the original field recordings made by ethnomusicologist Vera Solis in 1973 nor the subsequent studio remaster _______ the subtle quarter-tone intervals that distinguish the Palenquero drumming tradition from neighboring Afro-Colombian percussion styles.', $lyceon_json$[{"key":"A","text":"capture"},{"key":"B","text":"captures"},{"key":"C","text":"have captured"},{"key":"D","text":"are capturing"}]$lyceon_json$::jsonb, 'B', NULL, E'With a "neither...nor" construction, the verb agrees with the nearer subject. The nearer subject is "the subsequent studio remaster," which is singular, so the verb must be singular. The sentence describes a general truth about these recordings, so the simple present tense is appropriate. The choice "captures" is the singular present-tense form that correctly agrees with the nearer subject "remaster." The choice "capture" is plural and would incorrectly treat the compound subject as plural, violating the proximity-agreement rule for "neither...nor." The choice "have captured" uses a plural auxiliary ("have") that fails to agree with the singular nearer subject and shifts to the present perfect without contextual warrant. The choice "are capturing" uses a plural auxiliary and imposes a progressive aspect suggesting an ongoing temporary action, whereas the sentence states a permanent characteristic of the recordings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26CFY30', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the evidence presented in Text 2?', E'Text 1: Paleobotanist Elena Tsareva has argued that the extinction of large herbivorous mammals at the end of the Pleistocene triggered a cascade of vegetation changes across northern Eurasia. Without megafaunal grazing pressure, open grasslands were gradually overtaken by birch and willow scrub, which in turn altered soil nutrient cycling and fire regimes. Tsareva maintains that the loss of megafauna was the decisive factor, outweighing any concurrent climatic shifts.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26PHGR7', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Maria Koptjevskaja-Tamm has argued that languages spoken in colder climates tend to develop more elaborate lexicons for describing snow and ice formations, supporting the broader Sapir-Whorf hypothesis that environment shapes linguistic categories. Her 2017 cross-linguistic survey of forty-three Arctic and sub-Arctic languages documented significant variation in the granularity of frozen-precipitation terminology. _______ her data also revealed that several equatorial languages possess nuanced frost-related vocabulary borrowed through trade contact with highland communities, suggesting that environmental determinism alone cannot account for lexical specialization.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Yet"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first presents evidence supporting the idea that environment shapes language (cold-climate languages having elaborate snow vocabulary), then introduces a complicating finding: equatorial languages also possess frost-related vocabulary through trade. This second finding undermines the purely deterministic explanation, creating a contrast that "Yet" correctly signals. "Specifically," would indicate the sentence narrows or elaborates on the previous point, but it actually introduces a counterexample from an entirely different geographic context. "Consequently," implies the equatorial finding is a logical result of the Arctic survey data, which misrepresents the relationship — the equatorial finding is unexpected given the environmental determinism framework. "Likewise," suggests the equatorial data parallels the Arctic data in supporting the same conclusion, but the sentence explicitly states the opposite: the equatorial evidence complicates the environmental determinism model.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26S0M8P', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A marine biologist claims that the coral species Acropora tenella can survive prolonged periods of elevated water temperature better than most other Acropora species. Which finding, if true, would most directly support this claim?', E'Acropora corals are among the most temperature-sensitive reef-building genera in tropical oceans. Most Acropora species begin expelling their symbiotic algae — a process called bleaching — when water temperatures exceed their typical range by just 1 to 2 degrees Celsius for more than two weeks. However, field surveys conducted on reefs near Okinawa between 2017 and 2022 recorded that colonies of Acropora tenella retained their symbiotic algae through three separate marine heat waves, each lasting between 19 and 31 days, during which temperatures exceeded the local baseline by 2.3 degrees Celsius.', $lyceon_json$[{"key":"A","text":"A. tenella colonies near Okinawa retained symbiotic algae through heat waves lasting up to 31 days at 2.3 degrees Celsius above baseline, while most Acropora species bleach after two weeks at lower elevations."},{"key":"B","text":"Acropora corals as a genus are considered among the most temperature-sensitive reef builders in tropical waters worldwide."},{"key":"C","text":"Marine heat waves near Okinawa have become more frequent over the past decade, affecting multiple coral genera simultaneously."},{"key":"D","text":"Bleaching occurs when corals expel symbiotic algae in response to elevated temperatures, reducing the coral's ability to photosynthesize."}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that A. tenella survives prolonged elevated temperatures better than most Acropora species. The finding that A. tenella retained symbiotic algae through heat waves lasting up to 31 days at 2.3 degrees above baseline — conditions that would bleach other Acropora species — directly supports this comparative advantage. The choice about Acropora being temperature-sensitive describes the genus broadly and does not address A. tenella''s relative resilience. The choice about increasing heat wave frequency discusses environmental trends without comparing species-level tolerance. The choice defining bleaching explains a biological mechanism but provides no comparative evidence about A. tenella specifically.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW286GYKB', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A historian argues that the 1847 founding of Liberia as an independent republic did not reflect the genuine political aspirations of the indigenous Grebo and Kru populations who already inhabited the territory. Which quotation from a secondary source, if accurate, would most effectively support this argument?', E'Liberia''s 1847 constitution was drafted almost entirely by Americo-Liberian settlers — formerly enslaved people and free Black Americans who had emigrated under the auspices of the American Colonization Society. The document established English as the official language and modeled its governmental structure on that of the United States. Indigenous groups such as the Grebo and Kru, who comprised the majority of the territory''s population, were largely excluded from the constitutional convention and were not granted citizenship under the original charter. Tensions between settler elites and indigenous communities persisted well into the twentieth century.', $lyceon_json$[{"key":"A","text":"\"Of the 23 delegates at the 1847 constitutional convention, none represented Grebo, Kru, or any other indigenous community; all were Americo-Liberian settlers or their direct descendants.\""},{"key":"B","text":"\"The American Colonization Society initially intended Liberia as a haven for free Black Americans who faced discrimination in the United States during the early nineteenth century.\""},{"key":"C","text":"\"Liberia's 1847 constitution was notable for being the first republican charter adopted on the African continent, predating Ghana's independence by over a century.\""},{"key":"D","text":"\"Americo-Liberian settlers brought with them agricultural techniques from the American South, including cotton cultivation methods adapted to tropical climates.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The historian''s argument is that Liberia''s founding did not reflect indigenous political aspirations. The quotation stating that no indigenous representatives were among the 23 convention delegates directly supports this claim by showing indigenous groups had no voice in the republic''s creation. The quotation about the American Colonization Society''s intentions explains the settlers'' motivations but says nothing about indigenous exclusion from governance. The quotation about Liberia being the first African republican charter addresses the constitution''s historical significance, not whether it represented indigenous populations. The quotation about agricultural techniques concerns settler economic practices, which is unrelated to political representation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A0LJSZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Coral reefs support roughly one-quarter of all marine species despite occupying less than one percent of the ocean floor. Warming sea temperatures have triggered mass bleaching events that weaken reef structures and reduce biodiversity. _______ some coral species have shown an unexpected capacity to adapt by harboring heat-tolerant symbiotic algae, raising cautious optimism among marine biologists studying reef resilience.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"However,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first describes the damaging effects of warming temperatures on coral reefs, then pivots to an unexpected positive development: certain coral species adapting through heat-tolerant algae. This shift from a negative trend to a surprising counterpoint requires a contrast transition. "However," correctly signals that contrast. "Furthermore," would indicate additional information in the same direction, but the text reverses direction from harm to resilience. "Consequently," implies the adaptation is a direct result of the bleaching, misrepresenting the logical relationship since the sentence introduces a surprising counterexample rather than an expected consequence. "Similarly," suggests a parallel situation, but the capacity for adaptation is presented as contrasting with the destructive bleaching pattern, not echoing it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C23FL3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the text ("Yet the … rivers")?', E'Geomorphologists have long classified alluvial fans as depositional landforms, formed when sediment-laden water exits a steep canyon and spreads across a flatter surface. This classification implies a relatively static geometry once the fan is established. Yet the fans at the mouths of ephemeral desert rivers frequently migrate laterally by several meters per decade, as shifting storm tracks redirect peak discharge to different segments of the fan surface. Recent lidar surveys have documented this migration with sub-centimeter precision, prompting some researchers to argue that alluvial fans should be reclassified as dynamic rather than depositional features.', $lyceon_json$[{"key":"A","text":"It qualifies the traditional classification by introducing an observation that complicates it."},{"key":"B","text":"It provides an example that confirms the depositional classification of alluvial fans."},{"key":"C","text":"It describes the methodology used in lidar surveys of alluvial fans."},{"key":"D","text":"It summarizes the consensus view among geomorphologists about fan behavior."}]$lyceon_json$::jsonb, 'A', NULL, E'The third sentence begins with ''Yet,'' signaling a contrast with the preceding claim of static geometry. It introduces the observation that fans migrate laterally, which complicates the traditional depositional classification. The choice about qualifying the classification by introducing a complicating observation captures this function precisely. The option about confirming the depositional classification contradicts the contrastive role of the sentence. The option about lidar methodology confuses the third sentence with the fourth, where lidar surveys are mentioned. The option about summarizing consensus is wrong because the sentence challenges, rather than affirms, the established view.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C3689S', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geologist Mariana Okafor has spent nearly two decades studying volcanic calderas in the Ethiopian Rift _______ her research has reshaped how scientists model eruption cycles in continental rift zones.', $lyceon_json$[{"key":"A","text":"Valley, and"},{"key":"B","text":"Valley and,"},{"key":"C","text":"Valley, and,"},{"key":"D","text":"Valley and"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains two independent clauses joined by the coordinating conjunction "and." Standard English requires a comma before the coordinating conjunction when it joins two independent clauses. The choice "Valley, and" correctly places the comma before "and" to separate the clauses. The choice "Valley and," incorrectly places the comma after the conjunction. The choice "Valley, and," adds a spurious comma after the conjunction. The choice "Valley and" omits the required comma before the conjunction, creating a fused sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CMAP2O', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central idea of the text?', E'The fruit fly Drosophila suzukii, unlike most drosophilids, possesses a serrated ovipositor that allows it to pierce the skin of ripening fruit and deposit eggs inside intact berries. This trait has made D. suzukii a devastating agricultural pest since its arrival in North America in 2008. Yet recent work by entomologist Priya Chandrasekaran complicates the narrative of the ovipositor as a purely destructive adaptation. Chandrasekaran''s field experiments in wild blackberry thickets showed that D. suzukii oviposition wounds accelerate microbial colonization of overripe fruit, hastening decomposition and nutrient cycling back into the soil. In managed cropland, D. suzukii is unambiguously harmful; in unmanaged ecosystems, however, it may play an overlooked role in accelerating nutrient turnover.', $lyceon_json$[{"key":"A","text":"D. suzukii's serrated ovipositor, while destructive in agricultural contexts, may serve an ecologically beneficial function by accelerating decomposition in wild ecosystems."},{"key":"B","text":"Entomologist Priya Chandrasekaran has discovered a method for controlling D. suzukii infestations by exploiting the fly's oviposition behavior."},{"key":"C","text":"D. suzukii became a major agricultural pest in North America after 2008 because native berry species had no defense against its serrated ovipositor."},{"key":"D","text":"The microbial colonization triggered by D. suzukii oviposition wounds ultimately damages wild blackberry thickets beyond recovery."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central idea is that D. suzukii''s ovipositor, though harmful in agriculture, may benefit wild ecosystems by accelerating decomposition and nutrient cycling. The choice about a pest-control method misrepresents Chandrasekaran''s research, which characterized an ecological effect rather than proposing a control strategy. The choice about native berry defenses captures only the agricultural-pest aspect and introduces an unsupported claim about native species lacking defenses. The choice about irreversible damage to wild blackberry thickets contradicts the passage, which describes the decomposition effect as ecologically beneficial in unmanaged settings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D5ZLE9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what is the meaning of "plastic"?', E'Researchers studying cephalopod cognition have noted that octopus behavior is remarkably plastic. In laboratory trials, individual octopuses that initially failed to open latched containers learned to do so after observing a single demonstration, and they retained the technique for weeks afterward — adapting their grip depending on the container''s shape.', $lyceon_json$[{"key":"A","text":"synthetic"},{"key":"B","text":"fragile"},{"key":"C","text":"adaptable"},{"key":"D","text":"rigid"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes octopuses learning new techniques and adjusting their behavior, which signals that ''plastic'' means capable of change — that is, ''adaptable.'' ''Synthetic'' reflects the material-science meaning of plastic, which is irrelevant to a description of behavior. ''Fragile'' has no support in the passage; the octopuses demonstrate competence, not vulnerability. ''Rigid'' is the opposite of what the passage conveys, since the entire point is behavioral flexibility.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E0YSER', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological surveys of Bronze Age settlements along the Danube basin have revealed extensive networks of fortified granaries, suggesting that centralized grain storage was a hallmark of social organization in the region. Grain surplus likely enabled communities to sustain specialized labor classes, including metalworkers and potters. _______ the absence of comparable fortification around dwellings implies that communities prioritized protecting communal food reserves over individual households, complicating models that attribute early fortification solely to military defense.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"For instance,"},{"key":"C","text":"Notably,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence after the blank introduces a significant observation — the lack of fortification around dwellings — that adds a noteworthy and somewhat surprising dimension to the discussion by complicating existing models of fortification. "Notably," correctly signals that the point deserves special attention because it challenges conventional assumptions. "In addition," would merely add a parallel detail, but the sentence does more than extend the list; it introduces a finding that reframes the interpretation of fortification. "For instance," would indicate the sentence exemplifies something stated earlier, yet the point about absent dwelling fortification is not an illustration of centralized grain storage — it is a new observation with independent analytical weight. "Accordingly," implies the sentence follows logically as a consequence of the previous one, but the absence of dwelling fortification is not a result of grain surplus enabling specialized labor; it is a separate archaeological observation that shifts the argument.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EK6BIL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Millbrook Primate Center have documented that capuchin monkeys select stones of particular _______ a behavior suggesting that the animals evaluate tool properties before applying force to crack palm nuts.', $lyceon_json$[{"key":"A","text":"weight and hardness;"},{"key":"B","text":"weight, and hardness,"},{"key":"C","text":"weight and hardness,"},{"key":"D","text":"weight and hardness—"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase ''a behavior suggesting that the animals evaluate tool properties before applying force to crack palm nuts'' is an appositive noun phrase that renames and elaborates on the selection behavior described in the main clause. Since it is not an independent clause (the participle ''suggesting'' is not a finite verb), a semicolon is incorrect — semicolons require independent clauses on both sides. A comma correctly introduces this appositive. Inserting a comma between ''weight'' and ''and hardness'' incorrectly breaks the compound object of the preposition ''of.'' An em dash could introduce an appositive but is not the conventional choice in Standard English when a simple comma suffices and when the appositive flows directly from the main clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FMNTMG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'The fruit fly Drosophila melanogaster has served as a model organism in genetics since Thomas Hunt Morgan''s laboratory began breeding experiments in 1910. Its short generation time — roughly twelve days from egg to reproducing adult — allows researchers to observe inheritance patterns across dozens of generations within a single year. Moreover, with only four pairs of chromosomes, mapping individual genes to specific loci is far more tractable than it would be in organisms with larger genomes. These practical advantages explain why, even with modern genomic tools applicable to virtually any species, Drosophila remains one of the most studied animals in biology.', $lyceon_json$[{"key":"A","text":"It traces the historical development of genetics and then predicts future advances."},{"key":"B","text":"It introduces a phenomenon and then presents specific advantages that account for it."},{"key":"C","text":"It describes an experiment and then critiques its methodology."},{"key":"D","text":"It compares two organisms and then evaluates which is more useful for research."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage opens by noting the fruit fly''s long-standing role as a model organism (a phenomenon), then explains why: short generation time and a small number of chromosomes. The final sentence ties these specific advantages back to Drosophila''s continued prominence. The choice identifying this as introducing a phenomenon and presenting advantages is correct. The option about tracing history and predicting advances is wrong because the passage does not make predictions. The option about critiquing methodology is wrong because the passage endorses rather than criticizes the use of Drosophila. The option about comparing two organisms is wrong because no second organism is analyzed in detail.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GEEGDV', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Linguist Maren Solvik has argued that the rapid adoption of loanwords from English into Norwegian is eroding the distinctiveness of the Norwegian lexicon. She points out that between 2003 and 2019, over 1,400 English-origin terms entered standard Norwegian dictionaries, displacing native equivalents that had been in use for centuries.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GZEMYN', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'In 1846, the Hungarian physician Ignaz Semmelweis observed that the mortality rate in the maternity ward staffed by medical students was nearly five times higher than in the ward staffed by midwives. He hypothesized that the students were carrying infectious material from the autopsy room to the delivery ward. <u>When he required students to wash their hands in a chlorinated lime solution before examining patients, the mortality rate dropped from 18 percent to under 2 percent.</u> Despite this dramatic evidence, Semmelweis''s colleagues largely dismissed his findings.', $lyceon_json$[{"key":"A","text":"It provides evidence supporting Semmelweis's hypothesis."},{"key":"B","text":"It explains why medical students performed autopsies."},{"key":"C","text":"It describes a criticism leveled against Semmelweis."},{"key":"D","text":"It introduces a new hypothesis about infection."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes the result of Semmelweis''s handwashing intervention — the mortality rate plummeted — which directly supports his hypothesis that students were transmitting infectious material. The choice stating it provides evidence supporting the hypothesis correctly identifies this function. The option about autopsies misreads the passage; the sentence does not explain why autopsies were performed. The option about criticism confuses the underlined sentence with the final sentence, which mentions colleagues dismissing the findings. The option about a new hypothesis is wrong because the underlined sentence tests an existing hypothesis rather than proposing a different one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JCTYCM', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the central idea of the text?', E'In a 2019 study of 1,173 professional orchestral musicians across eleven countries, sociologist Ariadne Kavros found that musicians who regularly performed chamber music in addition to their orchestral duties reported markedly higher career satisfaction than those who performed only in full-orchestra settings. Kavros attributes this disparity not to financial incentives — chamber musicians rarely earn additional pay — but to the heightened sense of individual artistic agency that small-ensemble work provides. In a large orchestra, she notes, most musicians execute instructions from a conductor with little interpretive latitude; in a chamber group, each player shapes the musical outcome directly.', $lyceon_json$[{"key":"A","text":"Professional orchestral musicians who also play chamber music report greater career satisfaction, likely because chamber settings afford more individual artistic control."},{"key":"B","text":"Kavros's study proves that orchestral conductors suppress the creative autonomy of the musicians they lead, leading to widespread dissatisfaction."},{"key":"C","text":"Financial compensation is the primary factor driving professional musicians to seek chamber music engagements outside their orchestral positions."},{"key":"D","text":"A survey of 1,173 musicians revealed significant differences in career satisfaction across eleven countries studied by Kavros."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central point is that chamber music participation correlates with higher career satisfaction because it provides greater individual artistic agency — not because of pay. The choice claiming conductors ''suppress'' creativity and cause ''widespread dissatisfaction'' overstates the passage, which says only that orchestral settings offer less interpretive latitude. The choice about financial compensation directly contradicts the passage, which explicitly rules out financial incentives as the explanation. The choice about cross-country differences focuses on a methodological detail (sample size and geography) rather than the study''s main finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JP904S', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the ceramicist Tomoko Ishida moved to Albuquerque in 2014, she began experimenting with local clay deposits that _______ distinctive reddish hues to her glazes, a quality her earlier stoneware, produced in the Pacific Northwest, had lacked.', $lyceon_json$[{"key":"A","text":"lend"},{"key":"B","text":"lends"},{"key":"C","text":"has lent"},{"key":"D","text":"are lending"}]$lyceon_json$::jsonb, 'A', NULL, E'The relative pronoun "that" refers to "clay deposits," a plural noun. The verb in the relative clause must agree with this plural antecedent. The context describes a characteristic property of the deposits (they lend distinctive hues), so the simple present tense is appropriate. The choice "lend" is the plural present-tense form that correctly agrees with "deposits" and conveys a habitual property. The choice "lends" is singular and does not agree with the plural antecedent. The choice "has lent" uses a singular auxiliary and shifts to the present perfect without contextual justification. The choice "are lending" imposes a progressive aspect suggesting a temporary, ongoing action, but the sentence describes an inherent quality of the clay, not a temporary condition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JY3XYV', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late nineteenth century, ice harvesting — the practice of cutting blocks of ice from frozen lakes and rivers for commercial sale — was a major industry in the northeastern United States. Companies shipped natural ice as far south as the Caribbean and as far east as India. By 1886, however, the industry had begun a steep decline. Mechanical refrigeration technology, first demonstrated commercially in the 1870s, offered a year-round supply of ice unaffected by mild winters or water pollution — two problems that had caused severe shortages in 1880 and 1884. Although mechanical ice was initially more expensive per ton, its reliability attracted large-scale buyers such as meatpacking firms and breweries, who ________', $lyceon_json$[{"key":"A","text":"valued a predictable supply over a lower per-ton cost, since disruptions to their ice supply could halt production and spoil perishable inventory."},{"key":"B","text":"preferred natural ice for its superior clarity and taste, which customers increasingly demanded in premium food products."},{"key":"C","text":"had already invested heavily in ice-harvesting infrastructure and were reluctant to abandon those capital expenditures."},{"key":"D","text":"lobbied state legislatures to ban mechanical refrigeration in order to protect the natural ice industry from technological displacement."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that mechanical ice''s key advantage was reliability, and that natural ice had suffered supply disruptions from mild winters and pollution. For meatpacking firms and breweries — industries dependent on continuous refrigeration — unpredictable supply posed serious risks to production and inventory. The logical completion is that these buyers prioritized supply predictability over per-ton cost. The choice about preferring natural ice for clarity and taste contradicts the passage''s trajectory, which shows large buyers switching to mechanical ice. The choice about sunk costs in harvesting infrastructure introduces an economic consideration the passage never mentions and contradicts the stated shift toward mechanical ice. The choice about lobbying to ban mechanical refrigeration fabricates a political action unsupported by the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KW91K9', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A psycholinguist hypothesizes that bilingual speakers'' ability to suppress interference from their non-target language during speech production declines measurably when they are under cognitive load. Which experimental finding would most directly support this hypothesis?', E'When bilingual individuals speak in one language, their other language remains partially activated, creating potential interference. Researchers have proposed that a domain-general inhibitory control mechanism suppresses this cross-linguistic activation. If this mechanism draws on limited cognitive resources, then situations demanding additional cognitive effort — such as performing a concurrent task — should impair the bilingual speaker''s ability to suppress the non-target language, resulting in more cross-linguistic intrusions.', $lyceon_json$[{"key":"A","text":"Bilingual speakers produced significantly more unintended lexical borrowings from their non-target language when simultaneously performing an auditory digit-span task than when speaking without any concurrent task."},{"key":"B","text":"Bilingual speakers scored higher than monolingual speakers on a standardized measure of executive function, suggesting enhanced inhibitory control across both linguistic and non-linguistic domains."},{"key":"C","text":"Bilingual speakers who were highly proficient in both languages showed fewer cross-linguistic intrusions overall than bilingual speakers with asymmetric proficiency levels."},{"key":"D","text":"Bilingual speakers responded more slowly than monolingual speakers when asked to name pictures in their dominant language, even without any concurrent cognitive task."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis predicts that cognitive load reduces bilinguals'' ability to suppress the non-target language, producing more cross-linguistic intrusions. The finding that bilinguals produced significantly more unintended lexical borrowings under a concurrent digit-span task directly matches this prediction: cognitive load increased cross-linguistic interference. The finding about bilinguals outperforming monolinguals on executive function suggests enhanced inhibitory control, which would undermine rather than support the hypothesis. The finding about proficiency asymmetry addresses a different variable (proficiency level) without manipulating cognitive load. The finding about slower picture naming without a concurrent task describes a baseline bilingual disadvantage unrelated to the load-dependent decline the hypothesis specifies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LBXH06', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about the okapi for a wildlife magazine and wants to introduce the animal to readers who may be unfamiliar with it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LM6S2Y', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Fermentation has been used for millennia to preserve foods, yet the biochemical mechanisms underlying the process remained poorly understood until the nineteenth century. In 1857, Louis Pasteur demonstrated that living yeast cells were responsible for converting sugars into alcohol. _______ his work laid the foundation for the modern field of microbiology, influencing research on infectious disease, sanitation, and vaccine development.', $lyceon_json$[{"key":"A","text":"Ultimately,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank describes Pasteur''s specific demonstration, and the sentence after the blank describes the broader long-term outcome of that work. The relationship is one of culmination or final result, which "Ultimately," correctly signals. "Nevertheless," incorrectly implies a concession or contrast with what preceded, but the sentence continues in the same positive direction. "In contrast," wrongly suggests an opposing idea is being introduced, when the text builds on rather than opposes Pasteur''s finding. "Meanwhile," implies simultaneity with another event, but the passage is describing a consequence that followed from the discovery, not something happening at the same time.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MLO9OT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what is the meaning of "arresting"?', E'The geologist''s field notes from the 1987 expedition describe the basalt formations along the fjord as arresting. Columnar joints rose in near-perfect hexagonal cross-sections for forty meters, their uniformity so striking that early surveyors had mistaken them for engineered masonry. Even seasoned researchers paused to photograph them before proceeding with core sampling.', $lyceon_json$[{"key":"A","text":"detaining"},{"key":"B","text":"halting"},{"key":"C","text":"captivating"},{"key":"D","text":"alarming"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage emphasizes the visual impact of the basalt columns — their striking uniformity and the fact that even experienced researchers stopped to photograph them. ''Captivating'' correctly captures the sense of commanding attention through visual impressiveness. ''Detaining'' refers to physically holding someone in custody, which is irrelevant to geological description. ''Halting'' means causing to stop moving; while the researchers did pause, the word ''arresting'' here describes the formations themselves as impressive, not as physically obstructing movement. ''Alarming'' implies danger or fear, which contradicts the passage''s tone of admiration rather than anxiety.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NL6IY2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Elaine Weymouth studied 214 small-scale coffee farmers in the Oaxacan highlands of Mexico who had recently transitioned from conventional to certified organic farming. Organic certification promised access to premium export markets, but Weymouth found that only 29 of the 214 farmers actually received higher net income after the transition. The remaining farmers faced increased labor costs for manual weeding, purchased expensive approved inputs, and paid substantial annual certification fees — costs that frequently offset the price premium. Weymouth also noted that the 29 financially successful farmers shared a distinguishing characteristic: all belonged to established cooperatives that pooled certification costs and negotiated directly with international buyers, thereby ________', $lyceon_json$[{"key":"A","text":"eliminating the intermediary markups and distributing fixed certification expenses across enough members to keep per-farmer costs below the price premium each farmer earned."},{"key":"B","text":"guaranteeing that every cooperative member would earn a higher net income than any conventional farmer in the region regardless of yield variation."},{"key":"C","text":"enabling individual farmers to bypass organic certification requirements entirely and sell directly to international buyers at premium prices."},{"key":"D","text":"reducing the labor demands of organic farming by introducing mechanized weeding techniques that conventional farmers had already adopted."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage identifies two cost barriers — certification fees and intermediary markups — that prevented most farmers from benefiting financially from organic certification. The 29 successful farmers belonged to cooperatives that pooled certification costs and negotiated directly with buyers. The logical completion explains how these cooperative advantages worked: distributing fixed costs across members reduced per-farmer expenses, and direct negotiation eliminated intermediary markups, keeping costs below the premium earned. The choice guaranteeing higher income for every member overstates the finding; the passage does not claim cooperatives eliminated all financial risk. The choice about bypassing certification contradicts the passage, since the farmers are described as certified organic producers. The choice about mechanized weeding addresses labor costs but introduces a detail (mechanized techniques from conventional farming) that the passage never mentions and that would be inconsistent with organic certification requirements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NYS9WD', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the conservation team finishes cataloging the wetland species next August, the lead ecologist, Dr. Renata Otieno, _______ sediment cores from the estuary for nineteen consecutive months, making hers the longest continuous sampling effort in the reserve''s history.', $lyceon_json$[{"key":"A","text":"will have been collecting"},{"key":"B","text":"will collect"},{"key":"C","text":"has been collecting"},{"key":"D","text":"had been collecting"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence establishes a future reference point ("by the time the conservation team finishes... next August") and describes an action that will have been ongoing up to that point for a specified duration ("nineteen consecutive months"). The future perfect progressive ("will have been collecting") is required to express an action that started before a future moment and continues up to it with emphasis on duration. The choice "will collect" is simple future and does not convey the ongoing, cumulative nature of the activity up to a future deadline. The choice "has been collecting" is present perfect progressive and is inappropriate because the reference point is in the future, not the present. The choice "had been collecting" is past perfect progressive and places the action before a past reference point, but the sentence clearly refers to a future event (next August).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OUQHB6', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an essay for an art history seminar and wants to challenge the common assumption that Hilma af Klint''s abstract paintings were influenced by Wassily Kandinsky''s theoretical writings. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q9MK1W', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between Text 1 and Text 2?', E'Text 1: Architect Yui Hasegawa has proposed that municipal buildings should prioritize thermal mass — thick concrete or stone walls that absorb heat during the day and release it at night — as the primary strategy for reducing energy consumption. She argues that passive thermal regulation can cut heating and cooling costs by up to 37 percent in temperate climates, making expensive mechanical systems largely redundant.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TUX70W', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what is the meaning of "tempered"?', E'The glassblower''s initial enthusiasm for the commission was tempered by the realization that the client wanted seventeen identical vases completed within a single fortnight. Although she remained committed to the project, her excitement gave way to a more cautious optimism as she calculated the hours each piece would demand.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"abandoned"},{"key":"D","text":"intensified"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that the glassblower''s enthusiasm gave way to ''cautious optimism,'' indicating her excitement was reduced but not eliminated. ''Moderated'' correctly captures this sense of being restrained or lessened. ''Heated'' refers to the metallurgical meaning of tempering, which does not fit the emotional context here. ''Abandoned'' goes too far — the passage explicitly says she remained committed. ''Intensified'' contradicts the passage, since her excitement decreased rather than grew.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U3V9CT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The playwright Suki Nakamura often structures her dramas around overlapping _______ in her 2019 work "Copper Veins," for example, three separate storylines converge only in the final seven minutes of the performance.', $lyceon_json$[{"key":"A","text":"timelines:"},{"key":"B","text":"timelines;"},{"key":"C","text":"timelines,"},{"key":"D","text":"timelines, so"}]$lyceon_json$::jsonb, 'A', NULL, E'The material after the blank provides a specific example that illustrates the general claim made before the blank — that Nakamura structures her dramas around overlapping timelines. A colon is the conventionally correct mark to introduce an illustrative example or specification of a preceding independent clause. A semicolon after "timelines" would join two independent clauses but would not signal the illustrative relationship that "for example" establishes; when a colon already captures the explanatory function, the semicolon is the weaker choice because it treats the clauses as merely coordinate rather than as general-statement-plus-illustration. A comma after "timelines" creates a comma splice between two independent clauses. The choice "timelines, so" introduces a causal conjunction, but the second clause is an example of the first, not a consequence of it, making "so" logically inaccurate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U8LY0J', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand tree Corynocarpus laevigatus, known as karaka, contains a toxic glycoside called karakin that can cause severe neurological damage if ingested raw. Despite this toxicity, karaka berries were a staple food for Maori communities for centuries. Archaeological evidence from coastal village sites shows elaborate multi-step processing pits dating to at least the fourteenth century, in which berries were soaked in running water for several weeks before being steamed and dried. This labor-intensive preparation reliably neutralized the karakin, making the fruit safe to eat. The persistence of this practice across many generations suggests that ________', $lyceon_json$[{"key":"A","text":"the nutritional value of processed karaka berries was significant enough to justify the extensive effort required to render them safe for consumption."},{"key":"B","text":"Maori communities were unaware that raw karaka berries were toxic until European botanists identified karakin in the nineteenth century."},{"key":"C","text":"karaka trees were deliberately planted by Maori communities only after a reliable detoxification method had been discovered."},{"key":"D","text":"the karakin in karaka berries became less concentrated over time as a result of selective cultivation by Maori growers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Maori communities invested considerable labor over many generations to detoxify karaka berries. The most logical completion is that the berries'' nutritional value justified this sustained effort — otherwise the practice would not have persisted. The choice claiming Maori were unaware of the toxicity contradicts the passage, which shows they developed elaborate detoxification methods precisely because they knew the berries were dangerous raw. The choice about deliberate planting only after discovering detoxification introduces a chronological claim unsupported by anything in the text. The choice about decreasing karakin concentration through selective cultivation is unsupported; the passage attributes safety to processing, not to changes in the fruit itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UAAVCI', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the central idea of the text?', E'Researchers at the University of Helsinki have found that the Finnish ringed seal, once thought to rely exclusively on snow caves for pupping, can successfully rear offspring on bare ice when snow cover is insufficient. Between 2007 and 2014, the team documented 43 instances of pups born on exposed ice in Lake Saimaa, and 37 of those pups survived to weaning age. The finding challenges a decades-old assumption that adequate snow depth is a prerequisite for ringed seal reproduction, suggesting instead that the species possesses greater behavioral flexibility than previously recognized.', $lyceon_json$[{"key":"A","text":"Finnish ringed seals can reproduce successfully even without snow caves, demonstrating more behavioral flexibility than scientists had assumed."},{"key":"B","text":"Lake Saimaa's declining snow cover has caused a significant drop in the ringed seal population over the past two decades."},{"key":"C","text":"Researchers documented exactly 43 seal pups born on exposed ice during a seven-year observation period in Finland."},{"key":"D","text":"Ringed seals in Finland have evolved a new physiological adaptation that allows their pups to survive freezing temperatures without shelter."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the discovery that Finnish ringed seals can successfully rear pups on bare ice, overturning the assumption that snow caves are essential and revealing greater behavioral flexibility. The choice about declining population oversteps the passage, which never mentions population decline. The choice citing 43 pups on exposed ice captures a supporting detail rather than the central idea. The choice about physiological adaptation introduces a claim the passage does not make; the passage describes behavioral, not physiological, flexibility.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WU27AT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the municipal arborist and her crew of seven volunteers _______ more than two hundred saplings along the riverbank trails in Oxbow County.', $lyceon_json$[{"key":"A","text":"plants"},{"key":"B","text":"plant"},{"key":"C","text":"has planted"},{"key":"D","text":"is planting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject is "the municipal arborist and her crew of seven volunteers," a compound subject joined by "and," which is grammatically plural. The verb must therefore be plural. The choice "plant" is the correct plural present-tense verb agreeing with the compound subject. The choice "plants" is a singular verb form that would agree with only one of the subjects, not the compound. The choice "has planted" uses a singular auxiliary ("has") that does not agree with a plural subject. The choice "is planting" likewise uses a singular auxiliary ("is") that fails to agree with the plural compound subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z6NMIO', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about anaerobic digestion for an environmental engineering course and wants to emphasize the dual benefits of the process. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
